#include <stdio.h>  // fprintf, stderr

#include "codegen.h"  // cg_generate
#include "ctx.h"      // Shared memory and error context
// AI generated by: Codex / gpt-6.1-sol
// Prompt: "Fixed missing semantic analyze, fix the error"
// Changes: Use a correctly typed lexer adapter for the parser callback.
#include "lexer.h"
#include "lowering.h"
#include "optimizer.h"
#include "parser_internal.h"
#include "semantics.h"

// AI generated by: Codex / gpt-6.1-sol
// Prompt: "Fixed missing semantic analyze, fix the error"
// Changes: Adapt the lexer callback without an incompatible function-pointer cast.
static Token lexer_next(Ctx* ctx, void* source) {
  (void)source;
  Token token = next_token(ctx);
  // AI generated by: Codex / gpt-6.1-sol
  // Prompt: "Fixed missing semantic analyze, fix the error"
  // Changes: Normalize the lexer unit literal to the parser token contract.
  if (token.type == UNIT)
    token.type = TYPE_UNIT;
  return token;
}

/**
 * @brief Entrypoint of the IFJ26 compiler
 */
int main(int argc, char** argv) {
  // Parse CLI flags
  Flags flags;
  if (!parse_cli_args(argc, argv, &flags)) {
    fprintf(stderr, "Invalid CLI flag provided\n");
    return E_INTERNAL_ERROR;
  }

  // Initialize shared memory and error context
  static Ctx context;  // Static to survive long jump
  ctx_init(&context, flags);

  // If an error is thrown at any point during the program execution, an error
  // message will be printed to stderr and the CPU will jump back to here. If we
  // got here because of a thrown error, setjmp returns nonzero and we will
  // clean up and exit with the thrown error code.
  if (setjmp(context.error_target) != 0)
    return ctx_free(&context);

  // Allocate memory for the shared context
  ctx_allocate(&context);

  // Run the compiler
  // AI generated by: Codex / gpt-6.1-sol
  // Prompt: "Fixed missing semantic analyze, fix the error"
  // Changes: Parse through the typed lexer callback.
  parser_run(&context, lexer_next, &context.lexer);

  semantics_analyze(&context);

  lower_ast(&context);

  // AI generated by: Codex / gpt-6.1-sol
  // Prompt: "Fixed missing semantic analyze, fix the error"
  // Changes: Honor the flag used to compare optimized and unoptimized E2E runs.
  if (!context.flags.disableOptimizations)
    optimize_ir(&context);

  // Codegen
  cg_generate(stdout, &context);

  // Free allocated resources and exit
  return ctx_free(&context);
}
